   202  int LLVMFuzzerTestOneInput(const uint8_t *Data, size_t Size) {
   203      csh handle;
   204      cs_insn *all_insn;
   205      cs_detail *detail;
   206      cs_err err;
   207
   208      if (Size < 1) {
   209          // 1 byte for arch choice
   210          return 0;
   211      } else if (Size > 0x1000) {
   212          //limit input to 4kb
   213          Size = 0x1000;
   214      }
   215
   216      if (outfile == NULL) {
   217          // we compute the output
   218          outfile = fopen("/dev/null", "w");
   219          if (outfile == NULL) {
   220              return 0;
   221          }
   222      }
   223
   224      int platforms_len = sizeof(platforms)/sizeof(platforms[0]);
   225      int i = (int)Data[0] % platforms_len;
   226
   227      err = cs_open(platforms[i].arch, platforms[i].mode, &handle);
   228      if (err) {
   229          return 0;
   230      }
   231
   232      cs_option(handle, CS_OPT_DETAIL, CS_OPT_ON);
   233
   234      uint64_t address = 0x1000;
   235      size_t count = cs_disasm(handle, Data+1, Size-1, address, 0, &all_insn);
   236
   237      if (count) {
   238          size_t j;
   239          unsigned int n;
   240
   241          for (j = 0; j < count; j++) {
   242              cs_insn *i = &(all_insn[j]);
   243              fprintf(outfile, "0x%"PRIx64":\t%s\t\t%s // insn-ID: %u, insn-mnem: %s\n",
   244                     i->address, i->mnemonic, i->op_str,
   245                     i->id, cs_insn_name(handle, i->id));
   246
   247              detail = i->detail;
   248
   249              if (detail->regs_read_count > 0) {
   250                  fprintf(outfile, "\tImplicit registers read: ");
   251                  for (n = 0; n < detail->regs_read_count; n++) {
   252                      fprintf(outfile, "%s ", cs_reg_name(handle, detail->regs_read[n]));
   253                  }
   254              }
   255
   256              if (detail->regs_write_count > 0) {
   257                  fprintf(outfile, "\tImplicit registers modified: ");
   258                  for (n = 0; n < detail->regs_write_count; n++) {
   259                      fprintf(outfile, "%s ", cs_reg_name(handle, detail->regs_write[n]));
   260                  }
   261              }
   262
   263              if (detail->groups_count > 0) {
   264                  fprintf(outfile, "\tThis instruction belongs to groups: ");
   265                  for (n = 0; n < detail->groups_count; n++) {
   266                      fprintf(outfile, "%s ", cs_group_name(handle, detail->groups[n]));
   267                  }
   268              }
   269          }
   270
   271          fprintf(outfile, "0x%"PRIx64":\n", all_insn[j-1].address + all_insn[j-1].size);
   272          cs_free(all_insn, count);
   273      }
   274
   275      cs_close(&handle);
   276
   277      return 0;
   278  }
